    q12350: { h: "fb90c8ecfe97", text: "The bauxite-to-aluminium chain uses ore and a large amount of electricity: would you understand this hunger for electricity?" },
    q12351: { h: "b554c6618131", text: "The uranium business takes ore and yellowcake chemicals under strict rules: would you like buying by the rules?" },
