    q12358: { h: "c0987055804a", text: "A natural gas unit takes well casing and drying chemicals: would you understand casing pipe?" },
    q12359: { h: "ad4dcca35235", text: "The materials of an LNG unit are pipeline gas and electricity for cooling: would you enjoy the cooling chain?" },
