    q12366: { h: "9b8471dd7857", text: "An oil well service company takes cement slurry and testing tools: would you enjoy well cementing?" },
    q12367: { h: "8b6151ba86f6", text: "A solar unit orders cells, EVA sheets and glass: would you understand the cell import link?" },
    q12368: { h: "68783e4ac869", text: "The wind turbine business takes blade resin, steel towers and magnets: would you enjoy the blade materials?" },
