    q12384: { h: "56399b491c3c", text: "A sea exploration vessel gathers sensor buoys and deep cables: would you understand buoy materials?" },
    q13292: { h: "435241f3b91d", text: "Steel work is learned from an ITI and plant training: would you enjoy plant training?" },
